Variable R0 : bvmap 5 word.
Variable M0 : word -> option byte.
Variable model0 : Model.
Variables (sp ptr ra : Z).
Variable payload : list byte.
Variable LB0 : list (Z * Z).
Variable cr0 : credit.
Variable g : PMST.st.
Hypothesis Hgp : getr R0 (reg 3) = Z_to_bv 64 67584.
Hypothesis Htp : getr R0 (reg 4) = Z_to_bv 64 (pa_tp AD).

Abbreviation hcore := (PECH.hcore L R0 M0 model0 sp ra LB0).
Abbreviation vstr_at := (PM.vstr_at RSEGS PMSP.T3).
Abbreviation iss_at := (PM.iss_at RSEGS AD PMSP.T3).
Abbreviation enc_at := (PEC.enc_at RSEGS EE L PMSP.T3 PMSP.T4).
Abbreviation sink_at := (PESK.sink_at RSEGS L PMSP.T3 PMSP.T4 P).
Abbreviation fb := (PECH.fb sp).

(* [comment removed for export] *)
Definition G6a (R : bvmap 5 word) (M : word -> option byte) (model : Model) (cr : credit) (s s2 : PM.vstr) (sm : PM.strm)
           (tb : PM.vstr) (src : PM.srcst) (en : PEC.enc) (k : PESK.sink) (be : bool) : Prop :=
  hcore R M model /\ vstr_at M (fb + 792) s /\ PM.vs_size s = PECH.n payload
  /\ iss_at M (fb + 520) s2 sm /\ vstr_at M (fb + 384) tb
  /\ PM.src_fields_at RSEGS PMSP.T3 M (fb + 72) (fb + 520) (fb + 536) src /\ PM.nullis_at RSEGS AD PMSP.T3 M (fb + 80)
  /\ enc_at M (fb + 440) fb en /\ sink_at M (fb + 496) k
  /\ PECH.hstat M true true be /\ (PMST.st_err g = true -> be = true)
  /\ hi_heap HI (PM.src_own src ++ PM.vs_own tb ++ PEC.enc_own en ++ PESK.sink_own k ++ PM.vs_own s2 ++ PM.vs_own s ++ LB0) cr M (m_vmmaps model)
  /\ PMSP.credit_keep cr0 cr (PECH.P0 L P payload) (PESK.sink_pot P (PESK.sk_c k)).

(* [comment removed for export] *)
Definition G6p (R : bvmap 5 word) (M : word -> option byte) (model : Model) (cr : credit) (s s2 : PM.vstr) (sm : PM.strm)
           (src : PM.srcst) (en : PEC.enc) (k : PESK.sink) (be : bool) : Prop :=
  hcore R M model /\ vstr_at M (fb + 792) s /\ PM.vs_size s = PECH.n payload
  /\ iss_at M (fb + 520) s2 sm
  /\ PM.src_fields_at RSEGS PMSP.T3 M (fb + 72) (fb + 520) (fb + 536) src /\ PM.nullis_at RSEGS AD PMSP.T3 M (fb + 80)
  /\ enc_at M (fb + 440) fb en /\ sink_at M (fb + 496) k
  /\ PECH.hstat M true true be /\ (PMST.st_err g = true -> be = true)
  /\ hi_heap HI (PM.src_own src ++ PEC.enc_own en ++ PESK.sink_own k ++ PM.vs_own s2 ++ PM.vs_own s ++ LB0) cr M (m_vmmaps model)
  /\ PMSP.credit_keep cr0 cr (PECH.P0 L P payload) (PESK.sink_pot P (PESK.sk_c k))
  /\ getr R (reg 1) = Z_to_bv 64 215800 /\ getr R (reg 10) = Z_to_bv 64 (sp - 760).

(* [comment removed for export] *)
Definition G6b (R : bvmap 5 word) (M : word -> option byte) (model : Model) (cr : credit) (s s2 : PM.vstr) (sm : PM.strm)
           (en : PEC.enc) (k : PESK.sink) (be : bool) : Prop :=
  hcore R M model /\ vstr_at M (fb + 792) s /\ PM.vs_size s = PECH.n payload
  /\ iss_at M (fb + 520) s2 sm
  /\ enc_at M (fb + 440) fb en /\ sink_at M (fb + 496) k
  /\ PECH.hstat M true true be /\ (PMST.st_err g = true -> be = true)
  /\ hi_heap HI (PEC.enc_own en ++ PESK.sink_own k ++ PM.vs_own s2 ++ PM.vs_own s ++ LB0) cr M (m_vmmaps model)
  /\ PMSP.credit_keep cr0 cr (PECH.P0 L P payload) (PESK.sink_pot P (PESK.sk_c k)).

