Lemma src_gone :
  PMSP.opdel_spec RSEGS AD L HI -> PMSP.src_dtor_spec RSEGS AD L HI ->
  forall (fx : FPState) R M model cr s s2 sm tb src en k be K,
    G6a R M model cr s s2 sm tb src en k be -> K [] ->
    (forall (fx1 : FPState) R1 M1 model1,
        G6b R1 M1 model1 cr s s2 sm en k be ->
        srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x34af8 M1 model1) K) ->
